def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    index = {p: i for i, p in enumerate(cells)}
    pieces = []

    # Tile with 2x2 squares (color 1) and L triominoes.
    l_color = {
        0: 2,  # missing top-left
        1: 4,  # missing top-right
        2: 3,  # missing bottom-left
    }

    for r in range(h - 1):
        for c in range(w - 1):
            corners = [(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)]
            present = [p for p in corners if p in index]

            if len(present) == 4:
                mask = sum(1 << index[p] for p in present)
                pieces.append((mask, 1))

            if len(present) == 3:
                missing = next(i for i, p in enumerate(corners) if p not in index)
                if missing in l_color:
                    mask = sum(1 << index[p] for p in present)
                    pieces.append((mask, l_color[missing]))

            # Also consider Ls whose missing corner is occupied by a different tile.
            for missing, color in l_color.items():
                shape = [p for i, p in enumerate(corners) if i != missing]
                if all(p in index for p in shape):
                    mask = sum(1 << index[p] for p in shape)
                    pieces.append((mask, color))

    by_cell = [[] for _ in cells]
    for mask, color in set(pieces):
        for i in range(len(cells)):
            if mask >> i & 1:
                by_cell[i].append((mask, color))
    for options in by_cell:
        options.sort(key=lambda p: p[1] != 1)

    failed = set()

    def solve(remaining):
        if remaining == 0:
            return []
        if remaining in failed:
            return None

        i = (remaining & -remaining).bit_length() - 1
        for mask, color in by_cell[i]:
            if mask & remaining == mask:
                result = solve(remaining ^ mask)
                if result is not None:
                    return [(mask, color)] + result

        failed.add(remaining)
        return None

    tiling = solve((1 << len(cells)) - 1)
    out = [[0] * w for _ in range(h)]
    if tiling is not None:
        for mask, color in tiling:
            for i, (r, c) in enumerate(cells):
                if mask >> i & 1:
                    out[r][c] = color
    return out
